/*
 * MemoryIndicator.css — styling for the Memory_Register badge (Task 35.1;
 * Requirements 20.6, 20.7, 11.3).
 *
 * The badge is a small "M" chip shown only while the Memory_Register is
 * non-zero (Requirements 20.6/20.7 — the show/hide decision is made in TSX by
 * conditionally rendering the element; this file only styles the shown state).
 *
 * Contrast (Requirement 11.3): the badge is a graphical UI element, so its
 * boundary/graphic must keep >= 3:1 contrast against its adjacent background.
 * The real theme tuning lives in styles/theme.css (task 36); this file consumes
 * the shared tokens where available and falls back to colors that are already
 * clearly contrast-compliant:
 *   - label `#ffffff` on face `#303a5c`  -> 11.14:1 (text, Req 11.1, exceeds 11.3)
 *   - border `#8b9bd4` on face `#303a5c` -> ~4.10:1 (boundary/graphic, Req 11.3)
 * so the badge boundary stays >= 3:1 even before task 36 tunes the palette.
 */

.memory-indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.5rem;
  min-height: 1.5rem;
  padding: 0.1rem 0.4rem;

  font-family: inherit;
  font-size: 0.85rem;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.02em;

  /* Face + label meet text contrast; border keeps the badge boundary >= 3:1
     against the badge face (Requirement 11.3). Fallbacks are contrast-safe. */
  color: var(--color-digit-text, #ffffff);
  background-color: var(--color-digit-bg, #303a5c);
  border: 2px solid var(--color-border-digit, #8b9bd4);
  border-radius: var(--radius, 10px);
  user-select: none;
}

import "./MemoryIndicator.css";

/**
 * Props for {@link MemoryIndicator}.
 *
 * This is a presentational ("dumb") component: it owns no state and performs no
 * arithmetic or zero-check. The Calculator container (task 35.3) derives the
 * `active` flag by calling `isMemoryActive(memoryState)` from
 * `state/memoryReducer.ts` (which performs the exact decimal-string, non-float
 * zero-check) and passes the boolean down. The indicator is shown iff the
 * Memory_Register is non-zero (Requirements 20.6, 20.7).
 */
export interface MemoryIndicatorProps {
  /**
   * Whether the Memory_Register currently holds a non-zero value. The container
   * computes this via `isMemoryActive(memoryState)` — do NOT derive it here with
   * `parseFloat`/`Number`, so no float ever enters the zero-check path.
   */
  active: boolean;
}

/**
 * A small "M" badge signalling that the Memory_Register holds a stored value.
 *
 * - Renders the badge only while `active` is `true` (Requirement 20.6); returns
 *   `null` to render nothing when the register is zero (Requirement 20.7).
 * - Accessibility: the badge is a status element. It carries `role="status"`
 *   with `aria-live="polite"` so assistive technologies announce when memory
 *   becomes active without interrupting, and an `aria-label` describing the
 *   state in words rather than relying on the bare letter "M".
 * - Contrast: styling lives in `MemoryIndicator.css`, hooked to the shared
 *   theme tokens; the badge boundary/graphic stays >= 3:1 (Requirement 11.3).
 */
export function MemoryIndicator({ active }: MemoryIndicatorProps) {
  // Show iff the register is non-zero (Requirements 20.6/20.7).
  if (!active) {
    return null;
  }

  return (
    <span
      className="memory-indicator"
      role="status"
      aria-live="polite"
      aria-label="Memory contains a stored value"
    >
      M
    </span>
  );
}

export default MemoryIndicator;

import type { AngleMode } from "../api/types";
import CalcButton from "./CalcButton";

/**
 * Props for {@link AngleModeToggle}.
 *
 * Presentational component: the Calculator container (task 35.3) owns the
 * `angleMode` state and the flip logic. This control only DISPLAYS the active
 * mode (Requirement 22.6) and calls `onToggle` on activation to request a flip
 * (Requirement 22.7).
 */
export interface AngleModeToggleProps {
  /** The currently active angle unit for trigonometric evaluation. */
  angleMode: AngleMode;
  /**
   * Requests a flip to the other angle mode. The container flips the mode in
   * React state; that update is synchronous on click and re-renders immediately,
   * well within the 100 ms update budget (Requirement 22.7), so simply invoking
   * this callback satisfies the timing requirement.
   */
  onToggle: () => void;
}

/**
 * A toggle control that displays the active angle mode and flips it on
 * activation.
 *
 * - Displays the active mode as a short visible label — `RAD` for radians,
 *   `DEG` for degrees (Requirement 22.6).
 * - On activation it calls {@link AngleModeToggleProps.onToggle}; the container
 *   updates state immediately, so the displayed mode updates within 100 ms
 *   (Requirement 22.7).
 * - Reuses the Stage 1 {@link CalcButton} accessibility pattern (native
 *   `<button>`, visible label + matching `aria-label`, inherited focus/pressed
 *   state). The accessible name communicates both the current mode and that
 *   activating switches it (e.g. "Angle mode: radians. Activate to switch to
 *   degrees."). Uses the `action` variant.
 */
export function AngleModeToggle({ angleMode, onToggle }: AngleModeToggleProps) {
  const isRadians = angleMode === "radians";
  const label = isRadians ? "RAD" : "DEG";
  const otherMode = isRadians ? "degrees" : "radians";
  const ariaLabel = `Angle mode: ${angleMode}. Activate to switch to ${otherMode}.`;

  return (
    <CalcButton
      label={label}
      ariaLabel={ariaLabel}
      onActivate={onToggle}
      variant="action"
      className="angle-mode-toggle"
    />
  );
}

export default AngleModeToggle;
